alter table public.payments
  add column if not exists library_student_id uuid;

create table if not exists public.library_students (
  id uuid primary key default gen_random_uuid(),
  roll_number text not null,
  phone_number text,
  student_name text,
  seat_number text,
  locker_number text,
  start_time time,
  end_time time,
  slot_hours numeric(5,2),
  subscription_start_date date,
  subscription_end_date date,
  fee_amount numeric(12,2),
  paid_amount numeric(12,2),
  dues_amount numeric(12,2),
  advance_amount numeric(12,2),
  active boolean not null default true,
  placeholder boolean not null default false,
  status_note text,
  last_payment_id uuid references public.payments(id) on delete set null,
  last_payment_date date,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint library_students_roll_number_unique unique (roll_number),
  constraint library_students_roll_number_present check (char_length(btrim(roll_number)) > 0),
  constraint library_students_time_order check (start_time is null or end_time is null or start_time <> end_time)
);

alter table public.library_students
  drop constraint if exists library_students_time_order;

alter table public.library_students
  add constraint library_students_time_order
  check (start_time is null or end_time is null or start_time <> end_time);

alter table public.payments
  drop constraint if exists payments_library_student_id_fkey;

alter table public.payments
  add constraint payments_library_student_id_fkey
  foreign key (library_student_id) references public.library_students(id) on delete set null;

create table if not exists public.library_student_subscription_events (
  id uuid primary key default gen_random_uuid(),
  library_student_id uuid not null references public.library_students(id) on delete cascade,
  payment_id uuid references public.payments(id) on delete set null,
  event_key text not null unique,
  event_type text not null check (event_type in ('import_row', 'payment_renewal', 'manual_update', 'status_change')),
  event_date date not null default current_date,
  source text,
  subscription_start_date date,
  subscription_end_date date,
  fee_amount numeric(12,2),
  paid_amount numeric(12,2),
  dues_amount numeric(12,2),
  advance_amount numeric(12,2),
  seat_number text,
  locker_number text,
  start_time time,
  end_time time,
  active boolean,
  created_by uuid references public.profiles(id) on delete set null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists library_students_active_end_idx on public.library_students (active, subscription_end_date);
create index if not exists library_students_name_idx on public.library_students using gin (to_tsvector('simple', coalesce(student_name, '') || ' ' || roll_number || ' ' || coalesce(phone_number, '')));
create index if not exists payments_library_student_id_idx on public.payments (library_student_id);
create index if not exists library_student_events_student_date_idx on public.library_student_subscription_events (library_student_id, event_date desc);

drop trigger if exists touch_library_students_updated_at on public.library_students;
create trigger touch_library_students_updated_at before update on public.library_students
for each row execute function public.touch_updated_at();

create or replace function private.normalize_library_roll_number(value text)
returns text
language sql
immutable
set search_path = public
as $$
  select nullif(regexp_replace(btrim(coalesce(value, '')), '\.0+$', ''), '');
$$;

create temporary table library_students_import_raw (
  source_row integer not null,
  roll_number text not null,
  phone_number text,
  student_name text,
  seat_number text,
  locker_number text,
  start_time_text text,
  end_time_text text,
  subscription_end_date_text text,
  active_label text,
  status_note text,
  active boolean not null,
  placeholder boolean not null,
  metadata jsonb not null
) on commit drop;

