with ranked as (
  select *,
    row_number() over (
      partition by roll_number
      order by
        case
          when not placeholder and active then 0
          when not placeholder then 1
          else 2
        end,
        nullif(subscription_end_date_text, '')::date desc nulls last,
        source_row desc
    ) as rn
  from library_students_import_raw
), chosen as (
  select * from ranked where rn = 1
)
insert into public.library_students (
  roll_number, phone_number, student_name, seat_number, locker_number, start_time, end_time, slot_hours,
  subscription_end_date, active, placeholder, status_note, metadata
)
select
  roll_number,
  phone_number,
  student_name,
  seat_number,
  locker_number,
  nullif(start_time_text, '')::time,
  nullif(end_time_text, '')::time,
  case
    when nullif(start_time_text, '') is not null
      and nullif(end_time_text, '') is not null
      and nullif(start_time_text, '')::time < nullif(end_time_text, '')::time
    then extract(epoch from (nullif(end_time_text, '')::time - nullif(start_time_text, '')::time)) / 3600
    when nullif(start_time_text, '') is not null
      and nullif(end_time_text, '') is not null
      and nullif(start_time_text, '')::time > nullif(end_time_text, '')::time
    then 24 - extract(epoch from (nullif(start_time_text, '')::time - nullif(end_time_text, '')::time)) / 3600
    else null
  end,
  nullif(subscription_end_date_text, '')::date,
  active,
  placeholder,
  status_note,
  metadata || jsonb_build_object('import_selected_current', true)
from chosen
on conflict (roll_number) do update set
  phone_number = excluded.phone_number,
  student_name = excluded.student_name,
  seat_number = excluded.seat_number,
  locker_number = excluded.locker_number,
  start_time = excluded.start_time,
  end_time = excluded.end_time,
  slot_hours = excluded.slot_hours,
  subscription_end_date = excluded.subscription_end_date,
  active = excluded.active,
  placeholder = excluded.placeholder,
  status_note = excluded.status_note,
  metadata = public.library_students.metadata || excluded.metadata;

insert into public.library_student_subscription_events (
  library_student_id, event_key, event_type, event_date, source, subscription_end_date, seat_number, locker_number,
  start_time, end_time, active, metadata
)
select
  s.id,
  'excel-import-20260704-row-' || raw.source_row,
  'import_row',
  coalesce(nullif(raw.subscription_end_date_text, '')::date, current_date),
  'Library Timng and seat management (2).xlsx/STUDENTS',
  nullif(raw.subscription_end_date_text, '')::date,
  raw.seat_number,
  raw.locker_number,
  nullif(raw.start_time_text, '')::time,
  nullif(raw.end_time_text, '')::time,
  raw.active,
  raw.metadata
from library_students_import_raw raw
join public.library_students s on s.roll_number = raw.roll_number
on conflict (event_key) do nothing;

update public.payments p
set library_student_id = s.id
from public.library_students s
where p.business_type = 'library'
  and p.library_student_id is null
  and private.normalize_library_roll_number(p.roll_number) = s.roll_number;

update public.library_students s
set
  last_payment_id = latest.id,
  last_payment_date = latest.payment_date,
  subscription_start_date = coalesce(latest.start_date, s.subscription_start_date),
  subscription_end_date = coalesce(latest.end_date, s.subscription_end_date),
  fee_amount = coalesce(latest.fee_amount, s.fee_amount),
  paid_amount = coalesce(latest.paid_amount, s.paid_amount),
  dues_amount = coalesce(latest.dues_amount, s.dues_amount),
  advance_amount = coalesce(latest.advance_amount, s.advance_amount),
  active = case when s.placeholder then s.active else true end
from (
  select distinct on (library_student_id)
    id, library_student_id, payment_date, start_date, end_date, fee_amount, paid_amount, dues_amount, advance_amount
  from public.payments
  where business_type = 'library'
    and library_student_id is not null
    and record_status = 'active'
  order by library_student_id, payment_date desc, created_at desc
) latest
where s.id = latest.library_student_id;

alter table public.library_students enable row level security;
alter table public.library_student_subscription_events enable row level security;

drop policy if exists "library_students_select_collectors" on public.library_students;
create policy "library_students_select_collectors" on public.library_students
for select to authenticated
using ((select private.can_collect('library'::public.payment_business)));

drop policy if exists "library_students_insert_collectors" on public.library_students;
create policy "library_students_insert_collectors" on public.library_students
for insert to authenticated
with check ((select private.can_collect('library'::public.payment_business)));

drop policy if exists "library_students_update_collectors" on public.library_students;
create policy "library_students_update_collectors" on public.library_students
for update to authenticated
using ((select private.can_collect('library'::public.payment_business)))
with check ((select private.can_collect('library'::public.payment_business)));

drop policy if exists "library_student_events_select_collectors" on public.library_student_subscription_events;
create policy "library_student_events_select_collectors" on public.library_student_subscription_events
for select to authenticated
using ((select private.can_collect('library'::public.payment_business)));

drop policy if exists "library_student_events_insert_collectors" on public.library_student_subscription_events;
create policy "library_student_events_insert_collectors" on public.library_student_subscription_events
for insert to authenticated
with check ((select private.can_collect('library'::public.payment_business)));

drop policy if exists "library_student_events_update_collectors" on public.library_student_subscription_events;
create policy "library_student_events_update_collectors" on public.library_student_subscription_events
for update to authenticated
using ((select private.can_collect('library'::public.payment_business)))
with check ((select private.can_collect('library'::public.payment_business)));
